T = int(input())
while T:
	(N, K) = map(int, input().rstrip().rsplit())
	st = str(input())
	a = '01' * (N // 2)
	b = '10' * (N // 2)
	if N & 1:
		a += '0'
		b += '1'
	(n1, n2) = (0, 0)
	for i in range(N):
		if a[i] != st[i]:
			n1 += 1
		if b[i] != st[i]:
			n2 += 1
	if n1 <= K or n2 <= K:
		print(1)
	else:
		blocks = []
		count = 1
		for i in range(1, N):
			if st[i] != st[i - 1]:
				blocks.append(count)
				count = 1
			else:
				count += 1
		blocks.append(count)
		(l, r) = (2, N)
		while l < r:
			mid = (l + r) // 2
			c = 0
			for i in blocks:
				if i > mid:
					c += i // (mid + 1)
			if c > K:
				l = mid + 1
			else:
				r = mid
		print(l)
	T -= 1
